{
  "groups": [
    {
      "group_id": "ultra_low_fixed_rate_holders",
      "rule": "rate_type == 'fixed' and mortgage_rate_pct < 3.0 and origination_year == 2021",
      "rationale": "Borrowers locked into rock-bottom fixed rates face substantial payment shock at renewal, driving strong price sensitivity and active shop-around behavior."
    },
    {
      "group_id": "unhedged_variable_rate_borrowers",
      "rule": "rate_type == 'variable' and mortgage_rate_pct > 5.0",
      "rationale": "Variable rate holders experiencing elevated interest costs are prime candidates for negotiating rate stability or restructuring their loans."
    },
    {
      "group_id": "high_equity_prime_switchers",
      "rule": "insured_flag == False and credit_score_band == '720_plus' and mortgage_balance_cad > 350000",
      "rationale": "Uninsured prime credit borrowers with substantial balances represent highly lucrative targets for aggressive competitor retention offers."
    },
    {
      "group_id": "financially_constrained_families",
      "rule": "household_income_cad < 75000 and n_children >= 2 and mortgage_payment_monthly_cad > 2000",
      "rationale": "Lower-income households managing multiple children and heavy monthly obligations require tailored payment solutions to prevent default or churn."
    },
    {
      "group_id": "affluent_digital_investors",
      "rule": "household_income_cad >= 132505 and has_investments == True and channel == 'digital'",
      "rationale": "High-earning digital self-serve clients with investment relationships prioritize convenience and competitive digital terms."
    },
    {
      "group_id": "depleted_liquidity_insured_borrowers",
      "rule": "insured_flag == True and td_liquid_deposits_cad < 1000 and td_deposits_3m_change_cad < 0",
      "rationale": "Insured borrowers experiencing declining cash reserves face heightened budget sensitivity and require proactive outreach before term end."
    },
    {
      "group_id": "branch_engaged_retirees",
      "rule": "employment_status == 'retired' and has_advisor == True and channel == 'branch'",
      "rationale": "Retired clients relying on physical branch advisors value relationship management over pure rate-driven shopping."
    }
  ]
}
